actions.old_string:
def render(self, content: typing.Union[str, bytes, None]) -> bytes:
    if content is None:
        return b""
    if isinstance(content, bytes):
        return content
    return content.encode(self.charset)

actions.new_string:
def render(self, content: typing.Union[str, bytes, memoryview, None]) -> bytes:
    if content is None:
        return b""
    if isinstance(content, (bytes, memoryview)):
        return content
    return content.encode(self.charset)
